#!/usr/bin/env python3\nimport click\nimport subprocess\nimport concurrent.futures\nimport sys\n\n@click.group()\ndef cli():\n    \&quot;\&quot;Orch CLI - Orchestrate your shell tasks effortlessly.\n\n    Examples:\n        orch run \&quot;git pull\&quot; \&quot;npm test\&quot;\n        orch run task1 task2 --parallel\n    \&quot;\&quot;\n    pass\n\n@cli.command()\n@click.argument('tasks', nargs=-1, required=True)\n@click.option('--parallel/--sequential', default=False)\n@click.option('--quiet', '-q', is_flag=True)\ndef run(tasks, parallel, quiet):\n    \&quot;\&quot;Run tasks sequentially or in parallel.\n\n    TASKS: Shell commands to run.\n    \&quot;\&quot;\n    def execute(task):\n        try:\n            result = subprocess.run(task, shell=True, capture_output=True, text=True, timeout=300)\n            if not quiet:\n                if result.stdout:\n                    click.echo(result.stdout.rstrip())\n                if result.stderr:\n                    click.echo(result.stderr.rstrip(), err=True)\n            return 0 if result.returncode == 0 else 1\n        except subprocess.TimeoutExpired:\n            click.echo(f'Timeout: {task}', err=True)\n            return 1\n        except Exception as e:\n            click.echo(f'Error: {e}', err=True)\n            return 1\n\n    if parallel:\n        with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:\n            futures = [executor.submit(execute, task) for task in tasks]\n            for future in concurrent.futures.as_completed(futures):\n                future.result()\n    else:\n        for task in tasks:\n            execute(task)\n\nif __name__ == '__main__':\n    cli()